#!/usr/bin/env python3
import sys, os, gzip, bz2
HELP='''Ancient v2.3.0
Copyright (C) Teemu Suutari

Usage: ancient i[dentify] packed_input_files...
 - identifies compression used in a file(s)
Usage: ancient v[erify] packed_input_file unpacked_comparison_file
 - verifies decompression against known good unpacked file
Usage: ancient [-p] d[ecompress] packed_input_file output_file
 - decompresses single file
 - use p-flag to preserve timestamp of the original'''
def detect(b):
    if b.startswith(b'BZh'):
        try: bz2.decompress(b)
        except Exception: return None
        return ('bz2','bzip2')
    if b.startswith(b'\x1f\x8b'):
        try: gzip.decompress(b)
        except Exception: return None
        return ('gzip','Deflate')
    return None
def decode(b,t): return gzip.decompress(b) if t[0]=='gzip' else bz2.decompress(b)
def fail(s): print(s); return 1
def main(argv):
    preserve=False
    if argv and argv[0]=='-p': preserve=True; argv=argv[1:]
    if not argv or argv[0] not in ('i','identify','v','verify','d','decompress'):
        print(HELP); return 0
    cmd=argv[0][0]
    if (cmd=='i' and len(argv)<2) or (cmd in ('v','d') and len(argv)!=3): print(HELP); return 0
    names=argv[1:] if cmd=='i' else argv[1:2]
    for name in names:
        try:
            with open(name,'rb') as f: data=f.read()
        except OSError: return fail('Could not read file '+name)
        typ=detect(data)
        if typ is None:
            if cmd == 'i':
                print('Unknown or invalid compression format in file '+name)
                continue
