        if cmd=='i': print(f'Compression of {name} is {typ[0]}: {typ[1]}')
    if cmd=='i': return 0
    try: result=decode(data,typ)
    except Exception: return fail('Unknown or invalid compression format in file '+argv[1])
    if cmd=='v':
        try:
            with open(argv[2],'rb') as f: expected=f.read()
        except OSError: return fail('Could not read file '+argv[2])
        if result==expected: print('Files match!'); return 0
        if len(result) != len(expected):
            print(f'Verify failed for {argv[1]} and {argv[2]} - sizes differ')
        else:
            pos=next((i for i,(a,b) in enumerate(zip(result,expected)) if a!=b),0)
            print(f'Verify failed for {argv[1]} and {argv[2]} - contents differ @ {pos}')
